const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const thDate=s=>{if(!s)return '—';const d=new Date(s+'T12:00:00Z');return Number.isNaN(d.getTime())?s:d.toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});};
const duration=m=>{m=Number(m)||0;return (Math.floor(m/60)?Math.floor(m/60)+' ชม. ':'')+(m%60?m%60+' นาที':'')||'0 นาที';};
const price=s=>new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB'}).format(Number(s||0)/100);const initials=s=>String(s||'A').charAt(0).toUpperCase();
async function dialog(opts){if(window.Swal)return Swal.fire({confirmButtonColor:'#164b37',buttonsStyling:true,...opts});alert(opts.text||opts.title||'');return {isConfirmed:true};}
function message(text,error=false){return dialog({icon:error?'error':'success',title:error?'ไม่สำเร็จ':'ดำเนินการสำเร็จ',text:String(text),timer:error?undefined:2600,timerProgressBar:!error,showConfirmButton:!!error});}
async function copyStudentId(code){if(!code)return message('ยังไม่พบรหัสนักเรียน',true);try{await navigator.clipboard.writeText(String(code));await dialog({icon:'success',title:'คัดลอกรหัสนักเรียนแล้ว',text:'สามารถใช้ Student ID นี้เข้าสู่ระบบพร้อม PIN ได้',timer:2300,showConfirmButton:false});}catch{await dialog({title:'รหัสนักเรียนของคุณ',text:String(code),icon:'info'});}}
function rpc(name,...args){return PortalBridge.call(name,args);}
async function call(name,...args){try{return await rpc(name,...args);}catch(e){message(e.message,true);throw e;}}
