function pageHtml(){switch(app.view){case 'dashboard':return dashboard();case 'schedule':return schedulePage();case 'courses':return coursesPage();case 'history':return historyPage();case 'payments':return paymentsPage();case 'requests':return requestsPage();case 'progress':return progressPage();case 'profile':return profilePage();case 'chat':return awChatPage();case 'notifications':return awNotificationsPage();case 'groups':return awGroupPage();case 'rules':return awRulesPage();default:return dashboard();}}
function courseCard(c){
 const hour=c.mode==='hourly',out=app.data.billing.filter(b=>b.courseId===c.id).reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-Number(b.paid||0)),0),pct=percent(c.used,c.purchased);
 return `<article class="card course-tile"><div class="row course-tile-head"><span class="course-small-icon">${ico('book',21)}</span><div class="course-tile-title"><h3>${esc(c.title)} <span class="cycle-caption">· รอบ ${esc(c.cycle)}</span></h3><span class="tag ${hour?'info':''}">${hour?'รายชั่วโมง':'แพ็กเกจ'}</span></div></div><div class="mini-metrics">${hour?`<div><span class="small">ราคา/ชม.</span><strong>฿${Number(c.rate||0).toLocaleString('th-TH')}</strong></div><div><span class="small">เรียนแล้ว</span><strong>${duration(c.used)}</strong></div><div><span class="small">ค้างชำระ</span><strong>${price(out)}</strong></div>`:`<div><span class="small">ชั่วโมงทั้งหมด</span><strong>${duration(c.purchased)}</strong></div><div><span class="small">เรียนแล้ว</span><strong>${duration(c.used)}</strong></div><div><span class="small">คงเหลือ</span><strong>${duration(c.balance)}</strong></div>`}</div>${hour?'':`<div class="progress" aria-label="เรียนแล้ว ${pct}%"><span style="width:${pct}%"></span></div>`}<div class="buttons"><button class="btn" data-request="renew" data-course="${esc(c.id)}">${ico('rotate',16)} ขอต่อคอร์ส</button><button class="btn ghost" data-navto="history" data-course="${esc(c.id)}">${ico('clock',16)} ประวัติ</button>${hour&&out>0?`<button class="btn primary" data-navto="payments">${ico('wallet',16)} ยอดชำระ</button>`:''}</div></article>`;
}
