 const feature=featured?`<article class="feature-course"><div class="feature-top"><span class="feature-icon">${ico('book',26)}</span><span class="feature-tag">คอร์สปัจจุบัน</span></div><h3>${esc(featured.title)} <span>· รอบ ${esc(featured.cycle)}</span></h3><p>${featured.mode==='hourly'?'ติดตามเวลาเรียนและยอดค่าคาบ':'ติดตามความก้าวหน้าในการเรียนของคุณ'}</p>${featured.mode==='hourly'?`<div class="feature-progress-caption"><b>เรียนแล้ว ${duration(featured.used)}</b><b>รายชั่วโมง</b></div>`:`<div class="feature-progress"><div class="progress"><span style="width:${percent(featured.used,featured.purchased)}%"></span></div><div class="feature-progress-caption"><span>เรียนแล้ว ${duration(featured.used)} / ${duration(featured.purchased)}</span><strong>${percent(featured.used,featured.purchased)}%</strong></div></div>`}<button class="feature-link" data-navto="courses">ดูรายละเอียดคอร์ส ${ico('arrow-right',18)}</button></article>`:`<article class="feature-course"><span class="feature-icon">${ico('book',26)}</span><h3>เริ่มต้นการเรียนรู้</h3><p>คอร์สที่สมัครเรียนจะแสดงที่นี่เมื่อผู้ดูแลเปิดใช้งาน</p><button class="feature-link" data-request="new_course">สนใจลงคอร์สใหม่ ${ico('arrow-right',18)}</button></article>`;
 const shortcuts=[['schedule','calendar','ตารางเรียน','ดูคาบเรียนถัดไป'],['history','book-check','ประวัติการเรียน','ชั่วโมงเรียนย้อนหลัง'],['payments','wallet','ชำระเงิน','รายการและสลิป'],['requests','clipboard','คำขอ / การลา','แจ้งลาและชดเชย']];
